// The backend only sends the run id; everything else is read back from
// /assistant-m2m/runs/:runId/context and /tools.
const body = $json.body ?? {};
const runId = typeof body.runId === 'string' ? body.runId.trim() : '';
const valid =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(runId);

return { json: { valid, runId } };

// Runs after "Get context" and "Get tools".
//
// Output:
//   systemPrompt → AI Agent › Options › System Message  ({{ $json.systemPrompt }})
//   userPrompt   → AI Agent › Prompt (Define below)      ({{ $json.userPrompt }})
//   runId        → used by the executar_ferramenta tool  ({{ $('Build prompt').item.json.runId }})
//   sessionKey   → used by the Simple Memory node        ({{ $('Build prompt').item.json.sessionKey }})
//
// The system prompt carries instructions, the tool reference of the user's
// plan and the context of the day; everything the user or Jarvis said goes
// to the prompt as data inside tags.

const context = $('Get context').item.json;
const toolset = $('Get tools').item.json;
const runId = $('Config').item.json.runId;

// Angle brackets in user content are neutralised so a message can never
// close or open one of the context tags below (prompt-injection guard).
const escapeTags = (value) =>
  String(value ?? '').replace(/</g, '‹').replace(/>/g, '›');

const messages = [...(context.lastMessages ?? [])];
const ordered = messages.every((message) => message.createdAt)
  ? messages.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
  : messages.reverse(); // backend sends newest first

const history = ordered
  .filter(
    (message) =>
      !(message.type === 'AI' && /plano atual não inclui|não disponho de busca na web/i.test(String(message.content ?? ''))),
  )
  .map((message) => {
    const author = message.type === 'AI' ? 'jarvis' : 'usuario';
    return `<mensagem autor="${author}">${escapeTags(message.content)}</mensagem>`;
  })
  .join('\n');

const timezone = context.timezone || 'America/Sao_Paulo';
const fallbackNow = new Date();
const nowIso = context.now || fallbackNow.toISOString();
const nowHuman =
  context.nowHuman ||
  new Intl.DateTimeFormat('pt-BR', {
    timeZone: timezone,
    dateStyle: 'full',
    timeStyle: 'short',
  }).format(fallbackNow);

const rawProfileContext = (context.profileContext || '').trim();
const profileName = (context.profileName || '').trim();
const profileContext =
  [
    profileName && !/^Nome:/im.test(rawProfileContext)
      ? `Nome: ${profileName}`
      : '',
    rawProfileContext,
  ]
    .filter(Boolean)
    .join('\n') || 'Nenhuma informação adicional sobre o usuário.';

const sessionKey =
  typeof context.sessionKey === 'string' && context.sessionKey.trim()
    ? context.sessionKey.trim()
    : runId;

const knowledge = (Array.isArray(context.knowledge) ? context.knowledge : []).map(
  ({ id, name, description }) => ({ id, name, description }),
);

const cachedEvents = Array.isArray(context.cachedEvents)
  ? context.cachedEvents
  : [];

const rawDirective = String(context.directive ?? '')
  .replace(
    /- As ferramentas listadas são as que o plano do usuário inclui\.[^\n]*/g,
    '- Apenas quando o usuário pedir uma funcionalidade interna do Jarvis (lembretes, finanças ou base de conhecimento) ausente em "Ferramentas disponíveis", informe que faz parte de outro plano. Para buscas na web (clima, notícias, fatos atuais, eleições, cotações) ou dúvidas gerais, NUNCA diga que o plano não inclui: use a ferramenta browser_search.',
  );

const browserSearchReference = [
  '## Ferramenta direta "browser_search" (incluída em todos os planos): Busca na web em tempo real',
  'Quando usar: Sempre que o usuário pedir informações atuais, clima, notícias, eleições, cotações, fatos recentes ou pedir para pesquisar na web.',
  'Como chamar: Acione diretamente a tool `browser_search` passando o parâmetro `query` (NÃO use `executar_ferramenta` para ela).',
  'Importante: Você TEM acesso à busca na web em todos os planos. Ignore qualquer mensagem antiga em <historico_recente> onde tenha dito que não possui busca na web ou que o plano atual não inclui isso.',
].join('\n');

const systemPrompt = [
  rawDirective,
  '',
  toolset.reference ?? '',
  '',
  browserSearchReference,
  '',
  '# Contexto desta conversa',
  '',
  '<data_e_hora_atual>',
  `${nowHuman} (${nowIso}, fuso ${timezone})`,
  '</data_e_hora_atual>',
  '',
  '<perfil_do_usuario>',
  escapeTags(profileContext),
  '</perfil_do_usuario>',
  '',
  '<eventos_em_cache>',
  escapeTags(JSON.stringify(cachedEvents)),
  '</eventos_em_cache>',
  '',
  '<bases_de_conhecimento>',
  escapeTags(JSON.stringify(knowledge)),
  '</bases_de_conhecimento>',
  '',
  '<historico_recente>',
  history || 'Nenhuma mensagem anterior.',
  '</historico_recente>',
].join('\n');

const currentMessage = String(context.currentMessage ?? '');

const userPrompt = [
  '<mensagem_atual>',
  escapeTags(currentMessage),
  '</mensagem_atual>',
].join('\n');

return {
  json: {
    runId,
    sessionKey,
    hasMessage: currentMessage.trim().length > 0,
    systemPrompt,
    userPrompt,
  },
};

