    'string'
  )
}) }}

={{ JSON.stringify({
  model: 'openai/gpt-oss-120b',
  temperature: 0.2,
  tool_choice: 'required',
  tools: [{ type: 'browser_search' }],
  messages: [
    {
      role: 'system',
      content: 'Busque na web e responda de forma objetiva, precisa e em português do Brasil com os dados encontrados.'
    },
    {
      role: 'user',
      content: $fromAI(
        'query',
        'Pergunta ou termos claros de busca na web (inclua local e data/ano quando relevante, ex.: clima em São Paulo hoje).',
        'string'
      )
    }
  ]
}) }}

