const rawResponse = $json.output ?? $json.text;

const response =
  typeof rawResponse === 'string' && rawResponse.trim()
    ? rawResponse.trim()
    : 'Desculpe, tive um problema aqui e não consegui responder agora. Pode repetir?';

return {
  json: {
    response,
  },
};
